from collections import Counter

def play(secret, guesses):
    if len(secret) != 5 or not secret.isalpha() or not secret.islower():
        raise ValueError('invalid secret')
    history = []
    for guess in guesses[:6]:
        if len(guess) != 5 or not guess.isalpha() or not guess.islower():
            raise ValueError('invalid guess')
        marks = ['G' if a == b else 'X' for a, b in zip(secret, guess)]
        remaining = Counter(a for a, mark in zip(secret, marks) if mark != 'G')
        for index, letter in enumerate(guess):
            if marks[index] != 'G' and remaining[letter]:
                marks[index] = 'Y'
                remaining[letter] -= 1
        history.append({'word': guess, 'marks': ''.join(marks)})
        if guess == secret:
            break
    status = 'won' if history and history[-1]['marks'] == 'GGGGG' else 'lost' if len(history) == 6 else 'playing'
    return {'secret': secret, 'guesses': history, 'attempts': len(history), 'status': status}

